import express, { type Express } from 'express';
import type { CatalogueUseCases } from '../../application/catalogue/CatalogueModule';
import type { OrderUseCases } from '../../application/orders/OrderModule';
import { CatalogueController } from './controllers/CatalogueController';
import { OrderController } from './controllers/OrderController';
import { errorHandler, notFoundHandler } from './middleware/errorHandler';
import { requireStaff } from './middleware/staffAuth';
import { createRouter } from './routes';

export interface HttpAppDependencies {
  readonly orderUseCases: OrderUseCases;
  readonly catalogueUseCases: CatalogueUseCases;
  readonly staffApiKey: string;
}

export function createHttpApp(deps: HttpAppDependencies): Express {
  const app = express();
  app.disable('x-powered-by');
  app.use(express.json({ limit: '100kb' }));

  app.get('/health', (_req, res) => {
    res.json({ status: 'ok' });
  });
  app.use(
    createRouter(
      {
        orders: new OrderController(deps.orderUseCases),
        catalogue: new CatalogueController(deps.catalogueUseCases),
      },
      requireStaff(deps.staffApiKey),
    ),
  );

  app.use(notFoundHandler);
  app.use(errorHandler);
  return app;
}

=====SOURCE-END=====

