import { Router, type RequestHandler } from 'express';
import type { CatalogueController } from './controllers/CatalogueController';
import type { OrderController } from './controllers/OrderController';

export interface Controllers {
  readonly orders: OrderController;
  readonly catalogue: CatalogueController;
}

/**
 * Customer routes are open; warehouse operations and stock/order overviews
 * sit under /staff and require the staff key.
 */
export function createRouter(controllers: Controllers, staffOnly: RequestHandler): Router {
  const { orders, catalogue } = controllers;
  const router = Router();

  router.get('/products', catalogue.listCatalogue);
  router.post('/orders', orders.place);
  router.get('/orders/:id', orders.get);
  router.post('/orders/:id/pay', orders.changeStatus('pay'));
  router.post('/orders/:id/cancel', orders.changeStatus('cancel'));

  router.get('/staff/orders', staffOnly, orders.list);
  router.post('/staff/orders/:id/pack', staffOnly, orders.changeStatus('pack'));
  router.post('/staff/orders/:id/ship', staffOnly, orders.changeStatus('ship'));
  router.post('/staff/orders/:id/deliver', staffOnly, orders.changeStatus('deliver'));
  router.post('/staff/orders/:id/cancel', staffOnly, orders.changeStatus('cancel'));
  router.get('/staff/stock', staffOnly, catalogue.listStockLevels);
  router.post('/staff/products', staffOnly, catalogue.addProduct);

  return router;
}

=====SOURCE-END=====

